import * as T from './vendor/three.module.min.js';
import {batch} from './town.js';
const B=new T.BoxGeometry(1,1,1),S=new T.SphereGeometry(1,12,9),C=new T.CylinderGeometry(1,1,1,10),cone=new T.ConeGeometry(1,1,10),rock=new T.IcosahedronGeometry(1,1),materials=new Map();
function add(g,geo,c,x,y,z,w,h,d,rz=0){if(!materials.has(c))materials.set(c,new T.MeshStandardMaterial({color:c,roughness:.85}));const m=new T.Mesh(geo,materials.get(c));m.position.set(x,y,z);m.scale.set(w,h,d);m.rotation.z=rz;m.castShadow=m.receiveShadow=true;g.add(m);return m}
const box=(g,x,y,z,w,h,d,c)=>add(g,B,c,x,y,z,w,h,d),ball=(g,x,y,z,w,h,d,c)=>add(g,S,c,x,y,z,w,h,d),cyl=(g,x,y,z,r,h,c)=>add(g,C,c,x,y,z,r,h,r);
function pine(g,x,z,s=1,snow=false){cyl(g,x,2*s,z,.18*s,4*s,'#896b47');for(let k=0;k<4;k++){const y=(2.5+k*.84)*s;add(g,cone,snow?'#cbdcda':['#436e49','#568055','#688a55'][k%3],x,y,z,(1.7-k*.3)*s,2.3*s,(1.7-k*.3)*s);if(snow)add(g,cone,'#f3f5e7',x,y+.35*s,z,(1.4-k*.25)*s,1.8*s,(1.4-k*.25)*s);}}
function fence(g,x){for(let i=-10;i<12;i+=3){box(g,x,.7,i,.16,1.4,.16,'#8e7957');ball(g,x,1.43,i,.15,.09,.15,'#c5ae7b')}for(const y of [.48,1.05])box(g,x,y,0,.11,.12,23,'#c3aa77')}
function bridge(g,z){for(const side of [-1,1]){for(let k=-5;k<6;k+=2){box(g,side*5.9,1,z+k,.24,2,.24,'#89694a')}for(let k=0;k<2;k++)box(g,side*5.9,.6+k*.9,z,.13,.12,12,'#bd9568')}for(let k=-5;k<6;k++)box(g,0,.07,z+k,11.5,.10,.94,'#b19b71')}
function lamp(g,x,z){cyl(g,x,2.6,z,.07,5.2,'#5c5550');box(g,x,5.2,z,1,.14,.7,'#59473e');ball(g,x,4.85,z,.26,.35,.26,'#f8d58d')}
function forest(g,v){for(const side of [-1,1]){box(g,side*17,-.2,0,22,.3,24,'#7f9c5e');box(g,side*9,.04,0,3.6,.15,24,'#79b6b2');for(let k=0;k<7;k++){const z=-11+k*3.5;pine(g,side*(13+k%3*3),z,.9+(k%2)*.3);add(g,rock,'#9daba0',side*7.2,.4,z,.65,.42,.5);for(let j=0;j<3;j++){const x=side*(6.2+j*.27);cyl(g,x,.28,z,.025,.55,'#638949');ball(g,x,.58,z,.1,.08,.10,j%2?'#f4d89b':'#d5b7c4');}}
 for(let k=0;k<4;k++){const z=k*5-10;cyl(g,side*6.5,.27,z,.07,.48,'#e9d7ac');ball(g,side*6.5,.52,z,.26,.12,.24,'#bd6d52');ball(g,side*6.56,.60,z,.06,.015,.06,'#fff3d4')}fence(g,side*5.8);}if(v)bridge(g,0);}
function canyon(g,v){for(const side of [-1,1]){box(g,side*19,-.3,0,28,.35,24,'#c99864');for(let i=0;i<4;i++){const z=i*7-10,x=side*(10+i%2*4);add(g,rock,['#c28757','#ad704b','#d39c6a'][i%3],x,3+i%2*2,z,3.3,4+i%2*2,3);for(let j=0;j<4;j++)box(g,x,1+j*1.3,z,5.3-j*.6,.18,4.4-j*.35,'#e1af7c');cyl(g,side*6.9,.8,z,.18,1.6,'#64836a');cyl(g,side*7.35,1.3,z,.13,.75,'#64836a');box(g,side*7.13,1,z,.5,.15,.2,'#64836a');}
 fence(g,side*5.8);}
 if(v){for(const side of [-1,1]){box(g,side*5.8,3.9,0,.35,7.8,.5,'#715e49');box(g,side*5.8,7.8,0,.7,.2,.8,'#a28256')}box(g,0,7.8,0,12.5,.3,.7,'#a28256');for(let i=0;i<10;i++)box(g,-5.4+i*1.2,7.5,0,.09,.6,.12,'#bca273');}}
function coast(g,v){for(const side of [-1,1]){box(g,side*18,-.5,0,25,.5,24,'#56a9b2');box(g,side*8,-.1,0,5,.3,24,'#e1c994');for(let i=-10;i<11;i+=2)box(g,side*13,.03,i,3.1,.025,.06,'#a8ded4');for(let i=0;i<3;i++){const x=side*(7.4+i%2),z=-9+i*8;cyl(g,x,2.7,z,.14,5.4,'#a18a56');for(let j=0;j<7;j++){const a=j*Math.PI*2/7;const f=ball(g,x+Math.sin(a)*1.2,5.4,z+Math.cos(a)*1.2,.38,.14,1.55,'#65965a');f.rotation.y=a;f.rotation.z=Math.sin(a)*.17;}cyl(g,x-.2,5.15,z,.20,.35,'#ad9253');}
 fence(g,side*5.8);if(v){const x=side*10;cyl(g,x,1.2,2,.06,2.4,'#a18a56');add(g,cone,'#e2a46c',x,2.7,2,1.5,.7,1.5);box(g,x,.6,3,1,.12,1.8,'#f0dfb0');}}
 if(!v){const x=17;cyl(g,x,5,-2,1.45,10,'#ece5cc');cyl(g,x,5,-2,1.48,1.3,'#b96b58');cyl(g,x,10.3,-2,2,.35,'#5a7e7a');cyl(g,x,11,-2,1.3,1.1,'#a9d7cb');add(g,cone,'#b96b58',x,12,-2,1.8,1,1.8);}}
function market(g,v){for(const side of [-1,1]){box(g,side*12,-.1,0,12,.25,24,'#776c73');for(let i=0;i<3;i++){const x=side*9,z=-9+i*8;box(g,x,2,z,4.4,4,5.5,['#a8756c','#a28a77','#859b8a'][i]);box(g,x,4.1,z,5.2,.3,6.1,'#655d69');for(let j=0;j<5;j++){box(g,side*6.7,1.7,z-2+j*.9,.07,1.5,.66,'#e3bd86');box(g,side*6.6,1.7,z-2+j*.9,.08,.08,.7,'#72554e')}box(g,side*6.2,.9,z,.85,1.5,4,'#a47253');for(let j=0;j<5;j++)for(let k=0;k<2;k++)ball(g,side*(6+k*.24),1.72,z-1.5+j*.7,.18,.18,.19,k?'#b4bd66':'#e1ad5d');lamp(g,side*6.0,z+3);}}
 // Lantern strings overhead, with caps and tassels.
 for(const z of [-6,6]){box(g,0,6.6,z,13.5,.035,.035,'#655d57');for(let k=-3;k<=3;k++){const x=k*1.8,y=6.2-Math.cos(k*.4)*.3;cyl(g,x,y+.3,z,.018,.6,'#77654e');ball(g,x,y-.25,z,.31,.40,.31,k%2?'#c67d60':'#d9b46c');for(const yy of [-.61,.10])cyl(g,x,y+yy,z,.18,.07,'#7f594b');cyl(g,x,y-.78,z,.03,.29,'#cfa56a')}}}
function snow(g,v){for(const side of [-1,1]){box(g,side*18,-.2,0,25,.3,24,'#e2ece4');for(let k=0;k<5;k++){pine(g,side*(8+k%2*4),-10+k*5,1.0+(k%2)*.2,true);add(g,rock,'#c1d1ce',side*6.3,.4,-10+k*5,.6,.5,.8);}fence(g,side*5.8);if(v){box(g,side*12,1.5,0,4,3,6,'#a58c6b');add(g,cone,'#f0f2e9',side*12,3.5,0,3.4,2,4.1).rotation.y=Math.PI/4;box(g,side*9.95,1.8,0,.06,1.1,1.3,'#edce86');box(g,side*11.5,4.6,-1,.4,1.5,.4,'#928271');}}
 if(!v){for(let k=-1;k<=1;k++){const x=7.2,y=.45;ball(g,x,y+k*.05,3,.5,.5,.5,'#eff3e7')}ball(g,7.2,1.15,3,.36,.38,.36,'#edf3e7');for(const s of [-1,1])ball(g,7.2+s*.12,1.23,3.34,.04,.04,.03,'#4a534e');add(g,cone,'#c58b52',7.2,1.08,3.45,.055,.32,.055).rotation.x=Math.PI/2;}}
export const PALETTES=[['#c7ded8','#ffffff'],['#bed7c3','#b0b39a'],['#e2c5a2','#d6b38b'],['#b3dedf','#e5d5b0'],['#929ab8','#c0b0b0'],['#cadfe4','#dee9e2']];
export function createBiomes(parent){const root=new T.Group();parent.add(root);const layouts=[forest,canyon,coast,market,snow],groups=[];for(let j=0;j<5;j++){const zone=new T.Group();root.add(zone);const prototypes=[0,1].map(v=>{const q=new T.Group();layouts[j](q,v);return batch(q)});const chunks=[];for(let i=0;i<9;i++){const q=prototypes[i%2].clone();zone.add(q);chunks.push(q)}zone.visible=false;groups.push({zone,chunks});}
 return {root,update(distance,time,active){for(let j=0;j<groups.length;j++){const {zone,chunks}=groups[j];zone.visible=active===j+1;if(!zone.visible)continue;for(let i=0;i<chunks.length;i++)chunks[i].position.z=18-((i*24+216-distance%216)%216);}}};}
